const assert=require('node:assert/strict');
const {test}=require('node:test');
const {run}=require('./app');

for(const [action,status] of [['find','open'],['cancel','cancelled'],['archive','archived']]) {
  test(`${action}: trims surrounding whitespace and preserves order behavior`,()=>{
    for(const id of ['A1',' A1 ','\t\nA1\r\n','\u00a0A1\u3000']) {
      assert.deepEqual(run({action,id}),{id:'A1',status});
    }
    assert.deepEqual(run({action,id:' B2 '}),{id:'B2',status});
  });

  test(`${action}: rejects every invalid identifier`,()=>{
    for(const id of [undefined,null,'',' ','\t\r\n','\u00a0\u3000',0,1,false,true,{},[],['A1'],new String('A1')]) {
      assert.throws(()=>run({action,id}),{message:'invalid id'});
    }
    assert.throws(()=>run({action}),{message:'invalid id'});
  });

  test(`${action}: handles missing IDs without changing case or inner whitespace`,()=>{
    for(const id of ['unknown',' unknown ','a1',' a1 ','A 1']) {
      if(action==='find') assert.equal(run({action,id}),null);
      else assert.throws(()=>run({action,id}),{message:'missing'});
    }
  });
}

test('cancel and archive keep the stored order unchanged',()=>{
  run({action:'cancel',id:' A1 '});
  run({action:'archive',id:' A1 '});
  assert.deepEqual(run({action:'find',id:'A1'}),{id:'A1',status:'open'});
});

test('unsupported actions retain their error',()=>{
  assert.throws(()=>run({action:'unknown',id:'A1'}),{message:'action'});
});

