const rows=[{id:'A1',status:'open'},{id:'B2',status:'open'}];
function findOrder(id) {
  if(typeof id!=='string'||!id.trim()) throw Error('invalid id');
  const normalizedId=id.trim();
  return rows.find(row=>row.id===normalizedId)||null;
}
function run({action,id}) {
  if(!['find','cancel','archive'].includes(action)) throw Error('action');
  const row=findOrder(id);
  if(action==='find') return row;
  if(!row) throw Error('missing');
  return {...row,status:action==='cancel'?'cancelled':'archived'};
}
module.exports={run};
